export type ContractName = keyof typeof schemas;
export interface ContractContext {
  run_id?: string;
  target_id?: string;
}
export interface ValidationResult {
  valid: boolean;
  errors: string[];
}

const ajv = new Ajv2020({
  strict: true,
  allowUnionTypes: true,
  allErrors: true,
  validateFormats: true,
  coerceTypes: false,
  useDefaults: false,
  removeAdditional: false,
});
const addFormats = addFormatsImport as unknown as (
  instance: Ajv2020,
) => Ajv2020;
addFormats(ajv);
ajv.addKeyword({
  keyword: "x-ayran-schema-version",
  schemaType: "string",
  valid: true,
});
for (const schema of Object.values(schemas)) ajv.addSchema(schema);

function cloneWithoutIntegrity(value: unknown): unknown {
  const clone = structuredClone(value) as Record<string, unknown>;
  if (clone && typeof clone === "object") {
    if (clone.integrity && typeof clone.integrity === "object")
      delete (clone.integrity as Record<string, unknown>).content_hash;
    delete clone.event_hash;
  }
  return clone;
}

export function canonicalHash(value: unknown): string {
  const encoded = canonicalize(cloneWithoutIntegrity(value));
  if (encoded === undefined)
    throw new Error("Value is not JSON-canonicalizable");
  return `sha256:${createHash("sha256").update(encoded, "utf8").digest("hex")}`;
}

function contextualErrors(
  name: ContractName,
  value: Record<string, unknown>,
  context?: ContractContext,
): string[] {
  const errors: string[] = [];
  if (context?.run_id && value.run_id !== context.run_id)
    errors.push("run_id does not match contract context");
  const target = value.target_identity as Record<string, unknown> | undefined;
  if (context?.target_id && target?.target_id !== context.target_id)
    errors.push("target_id does not match contract context");
  if (name === "scope-manifest") {
    const seen = new Map<string, string>();
    for (const rule of (value.rules as
      Array<Record<string, string>> | undefined) ?? []) {
      const key = `${rule.action}\u0000${rule.resource}`;
      if (seen.has(key) && seen.get(key) !== rule.effect)
        errors.push("ambiguous allow/deny rule pair");
      seen.set(key, rule.effect);
    }
  }
  if (name === "graph-event") {
    if (value.seq === 1 && value.previous_event_hash !== null)
      errors.push("genesis event must have null previous_event_hash");
    if (
      typeof value.seq === "number" &&
      value.seq > 1 &&
      value.previous_event_hash === null
    )
      errors.push("non-genesis event requires previous_event_hash");
  }
  if (
    name === "evidence-artifact" &&
    value.evidence_grade === "validated" &&
    ["model_observation", "model_assumption", "curated_external"].includes(
      String(value.trust_class),
    )
  )
    errors.push("model or historical material cannot be validated evidence");
  const integrity = value.integrity as Record<string, unknown> | undefined;
  if (integrity) {
    const expected = new Set(
      name === "graph-event" || name === "journal-event"
        ? ["integrity.content_hash", "event_hash"]
        : ["integrity.content_hash"],
    );
    const actual = new Set(
      (integrity.excluded_fields as string[] | undefined) ?? [],
    );
    if (
      actual.size !== expected.size ||
      [...actual].some((item) => !expected.has(item))
    )
      errors.push(
        "integrity.excluded_fields does not match the contract hash rules",
      );
  }
  if (
    integrity?.content_hash &&
    integrity.content_hash !== canonicalHash(value)
  )
    errors.push(
      "integrity.content_hash does not match RFC 8785 canonical content",
    );
  if (
    (name === "graph-event" || name === "journal-event") &&
    value.event_hash !== canonicalHash(value)
  )
    errors.push("event_hash does not match canonical event content");
  return errors;
}

export function validateContract(
  name: ContractName,
  value: unknown,
  context?: ContractContext,
): ValidationResult {
  const schema = schemas[name];
  const validate = ajv.getSchema(schema.$id) ?? ajv.compile(schema);
  const valid = validate(value);
  const errors = valid
    ? []
    : (validate.errors ?? []).map(
        (e: ErrorObject) =>
          `${e.instancePath || "/"} ${e.message ?? "invalid"}`,
      );
  if (valid && value && typeof value === "object")
    errors.push(
      ...contextualErrors(name, value as Record<string, unknown>, context),
    );
  return { valid: errors.length === 0, errors };
}
